public with sharing class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    private static final Pattern CURRENCY_PATTERN = Pattern.compile('^[A-Z]{3}$');

    private class ExchangeRateResponse {
        public String base;
        public String date_x;
        public Map<String, Decimal> rates;
    }

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String normalizedBase = normalizeAndValidateCurrency(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies cannot be null or empty.');
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            normalizedQuotes.add(normalizeAndValidateCurrency(quote));
        }

        String symbolsParam = String.join(new List<String>(normalizedQuotes), ',');
        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base=' + normalizedBase + '&symbols=' + symbolsParam;

        HttpRequest req = buildRequest(endpoint);
        Http http = new Http();
        HttpResponse res;

        try {
            res = http.send(req);
            if (res.getStatusCode() == 503) {
                res = http.send(buildRequest(endpoint));
            }
        } catch (Exception e) {
            throw new ExchangeRateException('Callout failed: ' + e.getMessage(), e);
        }

        Integer statusCode = res.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException('Unexpected HTTP status code: ' + statusCode);
        }

        String body = res.getBody();
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Empty response body.');
        }

        ExchangeRateResponse parsedResponse;
        try {
            parsedResponse = (ExchangeRateResponse) JSON.deserialize(body, ExchangeRateResponse.class);
        } catch (Exception e) {
            throw new ExchangeRateException('Failed to parse response JSON: ' + e.getMessage(), e);
        }

        if (parsedResponse == null || parsedResponse.rates == null) {
            throw new ExchangeRateException('Response does not contain rates.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quote : normalizedQuotes) {
            if (!parsedResponse.rates.containsKey(quote) || parsedResponse.rates.get(quote) == null) {
                throw new ExchangeRateException('Missing rate for currency: ' + quote);
            }
            result.put(quote, parsedResponse.rates.get(quote));
        }

        return result;
    }

    private static HttpRequest buildRequest(String endpoint) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        return req;
    }

    private static String normalizeAndValidateCurrency(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code cannot be null.');
        }
        String normalized = code.trim().toUpperCase();
        if (!CURRENCY_PATTERN.matcher(normalized).matches()) {
            throw new ExchangeRateException('Invalid currency code: ' + code);
        }
        return normalized;
    }
}
