public with sharing class RecordSearchService {
    public class SearchException extends Exception {
    }

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name must not be blank.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field must be requested.');
            }
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            List<Schema.DescribeSObjectResult> objDescribes;
            try {
                objDescribes = Schema.describeSObjects(new List<String>{ objectApiName.trim() });
            } catch (Exception e) {
                throw new SearchException('Object does not exist: ' + objectApiName, e);
            }
            if (objDescribes == null || objDescribes.isEmpty()) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objDescribe = objDescribes[0];
            if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
                throw new SearchException('Insufficient access to object: ' + objDescribe.getName());
            }

            Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
            Set<String> selectFields = new Set<String>{ 'Id' };

            for (String fieldName : fields) {
                if (String.isBlank(fieldName)) {
                    throw new SearchException('Field name cannot be blank.');
                }
                Schema.SObjectField sField = fieldMap.get(fieldName.trim());
                if (sField == null) {
                    throw new SearchException('Invalid field: ' + fieldName);
                }
                Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                if (!fDescribe.isAccessible()) {
                    throw new SearchException('Field is not accessible: ' + fDescribe.getName());
                }
                selectFields.add(fDescribe.getName());
            }

            Map<String, Object> binds = new Map<String, Object>();
            List<String> whereClauses = new List<String>();

            if (filters != null && !filters.isEmpty()) {
                Integer bindIndex = 0;
                for (String filterKey : filters.keySet()) {
                    if (String.isBlank(filterKey)) {
                        throw new SearchException('Filter field name cannot be blank.');
                    }
                    Schema.SObjectField sField = fieldMap.get(filterKey.trim());
                    if (sField == null) {
                        throw new SearchException('Invalid filter field: ' + filterKey);
                    }
                    Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                    if (!fDescribe.isAccessible()) {
                        throw new SearchException('Filter field is not accessible: ' + fDescribe.getName());
                    }
                    if (!fDescribe.isFilterable()) {
                        throw new SearchException('Field cannot be filtered: ' + fDescribe.getName());
                    }

                    Object filterVal = filters.get(filterKey);
                    String bindKey = 'b' + bindIndex;
                    bindIndex++;
                    binds.put(bindKey, filterVal);
                    whereClauses.add(fDescribe.getName() + ' = :' + bindKey);
                }
            }

            String canonicalOrderBy = null;
            if (String.isNotBlank(orderByField)) {
                Schema.SObjectField sField = fieldMap.get(orderByField.trim());
                if (sField == null) {
                    throw new SearchException('Invalid order by field: ' + orderByField);
                }
                Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                if (!fDescribe.isAccessible()) {
                    throw new SearchException('Order by field is not accessible: ' + fDescribe.getName());
                }
                if (!fDescribe.isSortable()) {
                    throw new SearchException('Field cannot be sorted: ' + fDescribe.getName());
                }
                canonicalOrderBy = fDescribe.getName();
            }

            String soql =
                'SELECT ' +
                String.join(new List<String>(selectFields), ', ') +
                ' FROM ' +
                objDescribe.getName();

            if (!whereClauses.isEmpty()) {
                soql += ' WHERE ' + String.join(whereClauses, ' AND ');
            }

            if (canonicalOrderBy != null) {
                soql += ' ORDER BY ' + canonicalOrderBy + ' ASC';
            }

            soql += ' LIMIT ' + maxRows;

            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException(e.getMessage(), e);
        }
    }
}
