public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID' description='ID of the matched Contact')
        public Id contactId;

        @InvocableVariable(label='Found' description='Indicates whether a matching Contact was found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing Contact by email address')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<String> normalizedEmails = new Set<String>();
        for (Request req : requests) {
            if (req != null && String.isNotBlank(req.email)) {
                normalizedEmails.add(req.email.trim().toLowerCase());
            }
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!normalizedEmails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :normalizedEmails
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (String.isNotBlank(c.Email)) {
                    String key = c.Email.trim().toLowerCase();
                    if (!emailToContactId.containsKey(key)) {
                        emailToContactId.put(key, c.Id);
                    }
                }
            }
        }

        for (Request req : requests) {
            Result res = new Result();
            res.found = false;
            res.contactId = null;

            if (req != null && String.isNotBlank(req.email)) {
                String lookupKey = req.email.trim().toLowerCase();
                if (emailToContactId.containsKey(lookupKey)) {
                    res.contactId = emailToContactId.get(lookupKey);
                    res.found = true;
                }
            }
            results.add(res);
        }

        return results;
    }
}
