public with sharing class OrderPayloadParser {
    public class PayloadException extends Exception {
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Payload body cannot be null or blank.');
        }

        Object rawRoot;
        try {
            rawRoot = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON payload.', e);
        }

        if (!(rawRoot instanceof Map<String, Object>)) {
            throw new PayloadException('Payload root must be a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) rawRoot;

        Order result = new Order();

        Object rawNumber = root.get('number');
        if (!(rawNumber instanceof String) || String.isBlank((String) rawNumber)) {
            throw new PayloadException('Order number is required and cannot be blank.');
        }
        result.orderNumber = (String) rawNumber;

        Object rawDate = root.get('date');
        if (rawDate != null) {
            if (!(rawDate instanceof String)) {
                throw new PayloadException('Order date must be a string in yyyy-MM-dd format.');
            }
            String dateStr = (String) rawDate;
            if (String.isNotBlank(dateStr)) {
                try {
                    result.orderDate = Date.valueOf(dateStr);
                } catch (Exception e) {
                    throw new PayloadException('Invalid order date format: ' + dateStr, e);
                }
            }
        }

        Object rawCurrency = root.get('currency');
        if (rawCurrency != null) {
            if (!(rawCurrency instanceof String)) {
                throw new PayloadException('Currency must be a string.');
            }
            result.currencyCode = (String) rawCurrency;
        }

        Object rawCustomer = root.get('customer');
        if (rawCustomer != null) {
            if (!(rawCustomer instanceof Map<String, Object>)) {
                throw new PayloadException('Customer must be a JSON object.');
            }
            Map<String, Object> customerMap = (Map<String, Object>) rawCustomer;
            Object rawEmail = customerMap.get('email');
            if (rawEmail != null) {
                if (!(rawEmail instanceof String)) {
                    throw new PayloadException('Customer email must be a string.');
                }
                result.customerEmail = (String) rawEmail;
            }
        }

        result.lines = new List<Line>();
        result.total = 0;

        Object rawLines = root.get('lines');
        if (rawLines != null) {
            if (!(rawLines instanceof List<Object>)) {
                throw new PayloadException('Lines must be a JSON array.');
            }
            List<Object> lineList = (List<Object>) rawLines;
            for (Object rawLineObj : lineList) {
                if (!(rawLineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be a JSON object.');
                }
                Map<String, Object> lineMap = (Map<String, Object>) rawLineObj;
                Line lineItem = parseLine(lineMap);
                result.lines.add(lineItem);
                result.total += lineItem.lineTotal;
            }
        }

        return result;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line lineItem = new Line();

        Object rawSku = lineMap.get('sku');
        if (!(rawSku instanceof String) || String.isBlank((String) rawSku)) {
            throw new PayloadException('Line sku is required and cannot be blank.');
        }
        lineItem.sku = (String) rawSku;

        Object rawQuantity = lineMap.get('quantity');
        if (rawQuantity == null || !(rawQuantity instanceof Integer || rawQuantity instanceof Long || rawQuantity instanceof Decimal)) {
            throw new PayloadException('Line quantity is required and must be an integer.');
        }
        try {
            Decimal qDec = (Decimal) rawQuantity;
            if (qDec.scale() > 0 && qDec.stripTrailingZeros().scale() > 0) {
                throw new PayloadException('Line quantity must be a whole number.');
            }
            lineItem.quantity = qDec.intValue();
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Invalid line quantity.', e);
        }
        if (lineItem.quantity <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }

        Object rawUnitPrice = lineMap.get('unitPrice');
        if (rawUnitPrice == null || !(rawUnitPrice instanceof Decimal || rawUnitPrice instanceof Integer || rawUnitPrice instanceof Long || rawUnitPrice instanceof Double)) {
            throw new PayloadException('Line unitPrice is required and must be a number.');
        }
        lineItem.unitPrice = Decimal.valueOf(String.valueOf(rawUnitPrice));
        if (lineItem.unitPrice < 0) {
            throw new PayloadException('Line unitPrice cannot be negative.');
        }

        Object rawDiscount = lineMap.get('discount');
        if (rawDiscount == null) {
            lineItem.discount = 0;
        } else if (rawDiscount instanceof Decimal || rawDiscount instanceof Integer || rawDiscount instanceof Long || rawDiscount instanceof Double) {
            lineItem.discount = Decimal.valueOf(String.valueOf(rawDiscount));
            if (lineItem.discount < 0 || lineItem.discount > 1) {
                throw new PayloadException('Line discount must be between 0 and 1.');
            }
        } else {
            throw new PayloadException('Line discount must be a number.');
        }

        Decimal rawTotal = lineItem.quantity * lineItem.unitPrice * (1 - lineItem.discount);
        lineItem.lineTotal = rawTotal.setScale(2, RoundingMode.HALF_UP);

        return lineItem;
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order cannot be null.');
        }

        Integer lineCount = (order.lines == null) ? 0 : order.lines.size();
        Decimal total = (order.total == null) ? 0 : order.total;

        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        if (order.orderNumber != null) {
            gen.writeStringField('number', order.orderNumber);
        } else {
            gen.writeNullField('number');
        }
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', lineCount);
        gen.writeNumberField('total', total);
        gen.writeEndObject();

        return gen.getAsString();
    }
}
