        public String responseBody;
        public HttpRequest capturedRequest;
        public Integer callCount = 0;

        public VerificationMock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            this.callCount++;
            this.capturedRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(this.statusCode);
            if (this.responseBody != null) {
                res.setBody(this.responseBody);
            }
            return res;
        }
    }

    private static void assertRequestContract(HttpRequest req, Account expectedAcct) {
        Assert.isNotNull(req, 'Expected an HTTP callout to have been made');
        Assert.areEqual('callout:FB_Address_API/v2/verify', req.getEndpoint(), 'Endpoint mismatch');
        Assert.areEqual('POST', req.getMethod(), 'HTTP method mismatch');
        Assert.areEqual('application/json', req.getHeader('Content-Type'), 'Content-Type header mismatch');

        Map<String, Object> payload = (Map<String, Object>) JSON.deserializeUntyped(req.getBody());
        Assert.areEqual(4, payload.size(), 'Payload should contain exactly 4 keys');
        Assert.isTrue(payload.containsKey('street'), 'Payload missing street key');
        Assert.isTrue(payload.containsKey('city'), 'Payload missing city key');
        Assert.isTrue(payload.containsKey('postalCode'), 'Payload missing postalCode key');
        Assert.isTrue(payload.containsKey('country'), 'Payload missing country key');
        Assert.areEqual(expectedAcct.BillingStreet, (String) payload.get('street'), 'Street mismatch in request');
        Assert.areEqual(expectedAcct.BillingCity, (String) payload.get('city'), 'City mismatch in request');
        Assert.areEqual(expectedAcct.BillingPostalCode, (String) payload.get('postalCode'), 'PostalCode mismatch in request');
        Assert.areEqual(expectedAcct.BillingCountry, (String) payload.get('country'), 'Country mismatch in request');
    }

