    @IsTest
    static void testInsertClosedWonWithColdAccountAndCustomOwner() {
        User otherOwner = createTestUser();
        Account acc = new Account(Name = 'Cold Account', Rating = 'Cold');
        insert acc;

        Date closeDate = Date.today().addDays(10);
        Opportunity opp = new Opportunity(
            Name = 'Won On Insert',
            AccountId = acc.Id,
            OwnerId = otherOwner.Id,
            StageName = 'Closed Won',
            CloseDate = closeDate,
            NextStep = 'Initial Step'
        );

        Test.startTest();
        insert opp;
        Test.stopTest();

        Opportunity savedOpp = [SELECT Id, NextStep, OwnerId, CloseDate FROM Opportunity WHERE Id = :opp.Id];
        Assert.areEqual(
            'Handover to Customer Success',
            savedOpp.NextStep,
            'NextStep should be set to Handover to Customer Success on before insert'
        );

        List<Task> tasks = [
            SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId = :opp.Id
        ];
        Assert.areEqual(1, tasks.size(), 'Exactly one kick-off task should be created');
        Task t = tasks[0];
        Assert.areEqual('Customer kick-off', t.Subject, 'Task Subject should match');
        Assert.areEqual(opp.Id, t.WhatId, 'Task WhatId should be the opportunity Id');
        Assert.areEqual(otherOwner.Id, t.OwnerId, 'Task OwnerId should match the opportunity OwnerId');
        Assert.areEqual(closeDate.addDays(7), t.ActivityDate, 'Task ActivityDate should be CloseDate + 7 days');
        Assert.areEqual('High', t.Priority, 'Task Priority should be High');

        Account updatedAcc = [SELECT Id, Rating FROM Account WHERE Id = :acc.Id];
        Assert.areEqual('Hot', updatedAcc.Rating, 'Account Rating should be updated to Hot');
    }

