public with sharing class PicklistService {
    public class PicklistServiceException extends Exception {
    }

    public class Option {
        @AuraEnabled
        public String value { get; set; }
        @AuraEnabled
        public String label { get; set; }
        @AuraEnabled
        public Boolean isDefault { get; set; }

        public Option() {
        }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        String trimmedObjectName = objectApiName.trim();
        String trimmedFieldName = fieldApiName.trim();

        Schema.SObjectType sObjectType = Schema.getGlobalDescribe().get(trimmedObjectName);
        if (sObjectType == null) {
            throw new PicklistServiceException('Object does not exist: ' + trimmedObjectName);
        }

        Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe(SObjectDescribeOptions.DEFERRED);
        Schema.SObjectField sObjectField = objectDescribe.fields.getMap().get(trimmedFieldName);
        if (sObjectField == null) {
            throw new PicklistServiceException(
                'Field ' + trimmedFieldName + ' does not exist on object ' + trimmedObjectName + '.'
            );
        }

        Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + trimmedFieldName + ' on ' + trimmedObjectName + ' is not a picklist or multi-select picklist.'
            );
        }

        List<PicklistService.Option> options = new List<PicklistService.Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }

        return options;
    }
}
