public with sharing class OpportunityPipelineHandler {

    public static void handleTrigger(
        System.TriggerOperation operationType,
        List<Opportunity> newList,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        switch on operationType {
            when AFTER_INSERT, AFTER_UNDELETE {
                for (Opportunity opp : newList) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
            when AFTER_DELETE {
                for (Opportunity opp : oldMap.values()) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
            when AFTER_UPDATE {
                for (Opportunity opp : newList) {
                    Opportunity oldOpp = oldMap.get(opp.Id);
                    Boolean accountChanged = opp.AccountId != oldOpp.AccountId;
                    Boolean amountChanged = opp.Amount != oldOpp.Amount;
                    Boolean closedChanged = opp.IsClosed != oldOpp.IsClosed;

                    if (accountChanged || amountChanged || closedChanged) {
                        if (opp.AccountId != null) {
                            accountIds.add(opp.AccountId);
                        }
                        if (oldOpp.AccountId != null) {
                            accountIds.add(oldOpp.AccountId);
                        }
                    }
                }
            }
        }

        if (!accountIds.isEmpty()) {
            recalculateAccounts(accountIds);
        }
    }

    public static void recalculateAccounts(Set<Id> accountIds) {
        Map<Id, Account> accountsToCheck = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        if (accountsToCheck.isEmpty()) {
            return;
        }

        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();

        for (Id accId : accountsToCheck.keySet()) {
            pipelineByAccount.put(accId, 0);
            countByAccount.put(accId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountsToCheck.keySet()
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Decimal sumAmount = (Decimal) ar.get('totalAmount');
            Integer countOpps = (Integer) ar.get('openCount');

            pipelineByAccount.put(accId, sumAmount != null ? sumAmount : 0);
            countByAccount.put(accId, countOpps != null ? countOpps : 0);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : accountsToCheck.values()) {
            Decimal newPipeline = pipelineByAccount.get(acc.Id);
            Integer newCount = countByAccount.get(acc.Id);

            if (acc.FB_Open_Pipeline__c != newPipeline || acc.FB_Open_Opportunities__c != newCount) {
                acc.FB_Open_Pipeline__c = newPipeline;
                acc.FB_Open_Opportunities__c = newCount;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
