        DateTime now = DateTime.now();
        DateTime cutoff30 = now.addDays(-30);
        DateTime cutoff180 = now.addDays(-180);

        List<FB_Integration_Log__c> logsToPurge = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :cutoff30)
               OR (Level__c = 'ERROR' AND CreatedDate < :cutoff180)
            LIMIT 10000
        ];

        if (!logsToPurge.isEmpty()) {
            delete logsToPurge;
        }

        if (logsToPurge.size() == 10000) {
            Database.executeBatch(new LogPurgeJob(), 2000);
        }
    }

