            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :cutoff30)
               OR (Level__c = 'ERROR' AND CreatedDate < :cutoff180)
        ]);
    }

