public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        Set<Id> validAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                result.put(accountId, 0);
                validAccountIds.add(accountId);
            }
        }

        if (validAccountIds.isEmpty()) {
            return result;
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) totalWon
            FROM Opportunity
            WHERE AccountId IN :validAccountIds
                AND IsWon = true
                AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Decimal totalWon = (Decimal) ar.get('totalWon');
            result.put(accId, totalWon != null ? totalWon : 0);
        }

        return result;
    }
}
