public with sharing class Opportunities extends fflib_SObjectDomain {
    public static final String CLOSED_WON_STAGE = 'Closed Won';

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onAfterInsert() {
        Set<Id> wonOpportunityIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.StageName == CLOSED_WON_STAGE) {
                wonOpportunityIds.add(opp.Id);
            }
        }
        startFulfilmentFor(wonOpportunityIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> wonOpportunityIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (opp.StageName == CLOSED_WON_STAGE && (oldOpp == null || oldOpp.StageName != CLOSED_WON_STAGE)) {
                wonOpportunityIds.add(opp.Id);
            }
        }
        startFulfilmentFor(wonOpportunityIds);
    }

    private void startFulfilmentFor(Set<Id> opportunityIds) {
        if (opportunityIds != null && !opportunityIds.isEmpty()) {
            IOpportunityFulfilmentService service = (IOpportunityFulfilmentService) Application.Service.newInstance(
                IOpportunityFulfilmentService.class
            );
            service.startFulfilment(opportunityIds);
        }
    }
