public inherited sharing class CaseEscalationService {
    public class EscalationException extends Exception {
    }

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Escalation reason cannot be blank.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        if (cases == null || cases.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Date tomorrow = Date.today().addDays(1);
        Boolean hasEscalations = false;

        for (Case c : cases) {
            if (c.Status == 'Closed' || c.IsEscalated == true) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            Task followUp = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = tomorrow,
                Priority = 'High'
            );
            uow.registerNew(followUp);

            hasEscalations = true;
        }

        if (hasEscalations) {
            uow.commitWork();
        }
    }
}
