public inherited sharing class StaleOpportunityCloser {
    private static final String CLOSED_LOST_STAGE = 'Closed Lost';

    /**
     * Closes open opportunities with a CloseDate strictly before the given cutoff date.
     *
     * Note: While the SOQL for-loop in list form processes chunks of 200 to minimize
     * query cursor heap usage, DML is performed once outside the loop to avoid
     * hitting the 150 DML statement governor limit and repeated trigger execution overhead.
     * For volumes approaching or exceeding 10,000 records (or heavy Opportunity automation),
     * this logic should be moved to a Database.Batchable implementation.
     *
     * @param cutoff The date before which open opportunities are considered stale.
     * @return The number of opportunities transitioned to 'Closed Lost'.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        List<Opportunity> opportunitiesToUpdate = new List<Opportunity>();

        for (List<Opportunity> chunk : [
            SELECT Id
            FROM Opportunity
            WHERE IsClosed = FALSE AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = CLOSED_LOST_STAGE;
                opportunitiesToUpdate.add(opp);
            }
        }

        if (!opportunitiesToUpdate.isEmpty()) {
            update opportunitiesToUpdate;
        }

        return opportunitiesToUpdate.size();
    }
}
```

