public with sharing class AccountRatingService {
    private static final Decimal HOT_THRESHOLD = 100000;
    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    /**
     * Convenience overload for single Account Id callers.
     */
    public static void recalculate(Id accountId) {
        if (accountId != null) {
            recalculateAsync(new Set<Id>{ accountId });
        }
    }

    /**
     * Routes recalculation to a @future context when allowed by platform limits,
     * or executes synchronously if already running inside a future or batch context.
     */
    public static void recalculateAsync(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        Set<Id> cleanIds = new Set<Id>(accountIds);
        cleanIds.remove(null);
        if (cleanIds.isEmpty()) {
            return;
        }

        if (!System.isFuture() && !System.isBatch() && Limits.getFutureCalls() < Limits.getLimitFutureCalls()) {
            recalculate(cleanIds);
        } else {
            recalculateSync(cleanIds);
        }
    }

    /**
     * Bulkified @future method to recalculate Account Ratings asynchronously.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        recalculateSync(accountIds);
    }

    /**
     * Synchronously computes and updates the Rating for the provided Account IDs
     * based on their open Opportunities.
     */
    public static void recalculateSync(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> cleanIds = new Set<Id>(accountIds);
        cleanIds.remove(null);
        if (cleanIds.isEmpty()) {
            return;
        }

        // Default all target Accounts to Cold (no open opportunities)
        Map<Id, String> desiredRatings = new Map<Id, String>();
        for (Id accId : cleanIds) {
            desiredRatings.put(accId, RATING_COLD);
        }

        // Aggregate open opportunities per Account
        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) openCount, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :cleanIds AND IsClosed = FALSE
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Integer openCount = (Integer) ar.get('openCount');
            Decimal maxAmount = (Decimal) ar.get('maxAmount');

            if (openCount != null && openCount > 0) {
                if (maxAmount != null && maxAmount >= HOT_THRESHOLD) {
                    desiredRatings.put(accId, RATING_HOT);
                } else {
                    desiredRatings.put(accId, RATING_WARM);
                }
            }
        }

        // Query existing Accounts and only update records whose Rating actually changed
        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :cleanIds
        ]) {
            String newRating = desiredRatings.get(acc.Id);
            if (acc.Rating != newRating) {
                accountsToUpdate.add(new Account(Id = acc.Id, Rating = newRating));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

