public with sharing class LineItemDiscountHandler {
    public static void applyStandardDiscounts(List<OpportunityLineItem> lineItems) {
        if (lineItems == null || lineItems.isEmpty()) {
            return;
        }

        List<OpportunityLineItem> linesNeedingDiscount = new List<OpportunityLineItem>();
        Set<Id> productIds = new Set<Id>();
        Set<Id> pricebookEntryIds = new Set<Id>();

        for (OpportunityLineItem line : lineItems) {
            // Only apply default discount when Discount is null; preserve existing values (including 0)
            if (line.Discount == null) {
                linesNeedingDiscount.add(line);
                if (line.Product2Id != null) {
                    productIds.add(line.Product2Id);
                } else if (line.PricebookEntryId != null) {
                    pricebookEntryIds.add(line.PricebookEntryId);
                }
            }
        }

        if (linesNeedingDiscount.isEmpty()) {
            return;
        }

        // Resolve Product2Id from PricebookEntryId if Product2Id was not explicitly provided before insert
        Map<Id, Id> pbeToProductId = new Map<Id, Id>();
        if (!pricebookEntryIds.isEmpty()) {
            for (PricebookEntry pbe : [
                SELECT Id, Product2Id
                FROM PricebookEntry
                WHERE Id IN :pricebookEntryIds
            ]) {
                if (pbe.Product2Id != null) {
                    pbeToProductId.put(pbe.Id, pbe.Product2Id);
                    productIds.add(pbe.Product2Id);
                }
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // Single bulk SOQL query instead of calling PricingRules.standardDiscountFor(Id) per line
        Map<Id, Product2> productsById = new Map<Id, Product2>([
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
        ]);

        for (OpportunityLineItem line : linesNeedingDiscount) {
            Id prodId = line.Product2Id != null
                ? line.Product2Id
                : pbeToProductId.get(line.PricebookEntryId);

            Product2 prod = productsById.get(prodId);
            if (prod != null) {
                line.Discount = PricingRules.standardDiscountForFamily(prod.Family);
            }
        }
    }
}
