public with sharing class AccountCountrySync {

    /**
     * Synchronizes Contact MailingCountry when a parent Account's BillingCountry changes.
     * Updates contacts whose MailingCountry is currently blank or matches the Account's previous BillingCountry.
     *
     * @param newAccounts List of updated Account records (Trigger.new)
     * @param oldAccountMap Map of prior Account records (Trigger.oldMap)
     */
    public static void syncContactMailingCountry(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccountMap == null) {
            return;
        }

        // 1. Identify only the Accounts where BillingCountry actually changed
        Map<Id, Account> changedAccountsMap = new Map<Id, Account>();
        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountMap.get(acc.Id);
            if (oldAcc != null && hasCountryChanged(acc.BillingCountry, oldAcc.BillingCountry)) {
                changedAccountsMap.put(acc.Id, acc);
            }
        }

        // Exit early if no Account had a BillingCountry change (saves SOQL & CPU limits)
        if (changedAccountsMap.isEmpty()) {
            return;
        }

        // 2. Query only contacts belonging to the changed Accounts using the indexed AccountId field
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountsMap.keySet()
        ]) {
            Account newAcc = changedAccountsMap.get(con.AccountId);
            Account oldAcc = oldAccountMap.get(con.AccountId);

            // Update if Contact's MailingCountry is blank OR matches the Account's previous BillingCountry
            Boolean isContactCountryBlank = String.isBlank(con.MailingCountry);
            Boolean matchesPreviousAccountCountry = !String.isBlank(oldAcc.BillingCountry) &&
                !isContactCountryBlank &&
                con.MailingCountry.trim().equalsIgnoreCase(oldAcc.BillingCountry.trim());

            if (isContactCountryBlank || matchesPreviousAccountCountry) {
                // Only add to DML list if the value actually needs to change on the Contact
                if (hasCountryChanged(con.MailingCountry, newAcc.BillingCountry)) {
                    con.MailingCountry = newAcc.BillingCountry;
                    contactsToUpdate.add(con);
                }
            }
        }

        // 3. Perform a single bulk DML update
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    /**
     * Helper to accurately check if two country strings differ, treating null and empty string as equivalent,
     * while respecting case changes (e.g., 'usa' -> 'USA').
     */
    private static Boolean hasCountryChanged(String newCountry, String oldCountry) {
        Boolean newIsBlank = String.isBlank(newCountry);
        Boolean oldIsBlank = String.isBlank(oldCountry);

        if (newIsBlank && oldIsBlank) {
            return false;
        }
        if (newIsBlank != oldIsBlank) {
            return true;
        }
        return !newCountry.equals(oldCountry);
    }
}
```

