import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage = '';

    timeoutId;
    latestRequestId = 0;

    disconnectedCallback() {
        this.clearPendingSearch();
        this.latestRequestId++;
    }

    clearPendingSearch() {
        if (this.timeoutId) {
            clearTimeout(this.timeoutId);
            this.timeoutId = null;
        }
    }

    handleSearchChange(event) {
        this.clearPendingSearch();

        const rawValue = event.target?.value ?? event.detail?.value ?? '';
        const searchTerm = rawValue.trim();

        if (searchTerm.length < 2) {
            this.latestRequestId++;
            this.contacts = [];
            this.errorMessage = '';
            return;
        }

        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this.timeoutId = setTimeout(() => {
            this.timeoutId = null;
            this.executeSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    async executeSearch(searchTerm) {
        const requestId = ++this.latestRequestId;

        try {
            const result = await searchContacts({ searchTerm });
            if (requestId === this.latestRequestId) {
                this.contacts = result || [];
                this.errorMessage = '';
            }
        } catch (error) {
            if (requestId === this.latestRequestId) {
                this.contacts = [];
                this.errorMessage = error?.body?.message || error?.message || 'An unexpected error occurred';
            }
        }
    }
}
