    get hasError() {
        return !this.isLoading && Boolean(this.errorMessage);
    }

    get hasOpportunities() {
        return !this.isLoading && !this.errorMessage && this.opportunities.length > 0;
    }

    get isEmpty() {
        return !this.isLoading && !this.errorMessage && this.opportunities.length === 0;
    }
}
