import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _intervalId = null;
    _inFlight = false;
    _isConnected = false;
    _boundHandleVisibilityChange;

    connectedCallback() {
        this._isConnected = true;
        this._boundHandleVisibilityChange = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._boundHandleVisibilityChange);

        if (document.visibilityState !== 'hidden') {
            this.fetchStats();
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this._isConnected = false;
        this.stopPolling();
        if (this._boundHandleVisibilityChange) {
            document.removeEventListener('visibilitychange', this._boundHandleVisibilityChange);
            this._boundHandleVisibilityChange = null;
        }
    }

    handleVisibilityChange() {
        if (!this._isConnected) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.fetchStats();
            this.startPolling();
        }
    }

    startPolling() {
        this.stopPolling();
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._intervalId = setInterval(() => {
            this.fetchStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    async fetchStats() {
        if (!this._isConnected || document.visibilityState === 'hidden' || this._inFlight) {
            return;
        }

        this._inFlight = true;
        try {
            const result = await getQueueStats();
            if (this._isConnected) {
                this.stats = result;
                this.errorMessage = undefined;
            }
        } catch (error) {
            if (this._isConnected) {
                this.errorMessage = error?.body?.message || error?.message || 'Error loading queue stats';
            }
        } finally {
            this._inFlight = false;
        }
    }
}
