import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeIndex = -1;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this.syncActiveIndexToValue();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this.syncActiveIndexToValue();
    }

    syncActiveIndexToValue() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = -1;
            return;
        }
        const selectedIndex = this._options.findIndex(
            (opt) => opt.value === this._value
        );
        this._activeIndex = selectedIndex !== -1 ? selectedIndex : 0;
    }

    get computedOptions() {
        return (this._options || []).map((opt, index) => {
            const isSelected = opt.value === this._value;
            const isActive = index === this._activeIndex;
            return {
                id: `option-${index}`,
                value: opt.value,
                label: opt.label,
                ariaSelected: isSelected ? 'true' : 'false',
                className: `slds-listbox__option slds-listbox__option_plain slds-media slds-media_small${
                    isSelected ? ' slds-is-selected' : ''
                }${isActive ? ' slds-has-focus' : ''}`
            };
        });
    }

    get activeDescendantId() {
        if (
            this._activeIndex >= 0 &&
            this._activeIndex < this._options.length
        ) {
            return this.template.querySelector(
                `[data-index="${this._activeIndex}"]`
            )?.id;
        }
        return undefined;
    }

    renderedCallback() {
        const listbox = this.template.querySelector('[role="listbox"]');
        if (!listbox) {
            return;
        }
        if (
            this._activeIndex >= 0 &&
            this._activeIndex < this._options.length
        ) {
            const activeOption = this.template.querySelector(
                `[data-index="${this._activeIndex}"]`
            );
            if (activeOption && activeOption.id) {
                listbox.setAttribute('aria-activedescendant', activeOption.id);
            } else {
                listbox.removeAttribute('aria-activedescendant');
            }
        } else {
            listbox.removeAttribute('aria-activedescendant');
        }
    }

    handleKeyDown(event) {
        const len = this._options ? this._options.length : 0;

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (len > 0) {
                    this._activeIndex = Math.min(
                        len - 1,
                        Math.max(0, this._activeIndex) + 1
                    );
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (len > 0) {
                    this._activeIndex = Math.max(0, this._activeIndex - 1);
                }
                break;
            case 'Home':
                event.preventDefault();
                if (len > 0) {
                    this._activeIndex = 0;
                }
                break;
            case 'End':
                event.preventDefault();
                if (len > 0) {
                    this._activeIndex = len - 1;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                if (this._activeIndex >= 0 && this._activeIndex < len) {
                    this.selectOptionByIndex(this._activeIndex);
                }
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const li = event.currentTarget;
        const index = Number(li.dataset.index);
        if (!Number.isNaN(index)) {
            this.selectOptionByIndex(index);
        }
    }

    selectOptionByIndex(index) {
        if (!this._options || index < 0 || index >= this._options.length) {
            return;
        }
        this._activeIndex = index;
        const nextValue = this._options[index].value;
        if (this._value !== nextValue) {
            this._value = nextValue;
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value: nextValue }
                })
            );
        }
    }
}
