public with sharing class EmployerService {

    /**
     * Updates the primary affiliation for each Contact in the map to the specified Organization Account.
     * Relies on NPSP's AFFL_Affiliations_TDTM trigger on Contact.npsp__Primary_Affiliation__c to
     * automatically create the new primary Current Affiliation and mark any previous primary
     * Affiliation as Former, non-primary with an End Date of today, while keeping the Contact
     * in its Household Account.
     *
     * @param employerByContactId Map of Contact Id to Organization Account Id
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>(employerByContactId.keySet());
        contactIds.remove(null);
        if (contactIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            Id newEmployerId = employerByContactId.get(c.Id);
            if (newEmployerId != null && c.npsp__Primary_Affiliation__c != newEmployerId) {
                c.npsp__Primary_Affiliation__c = newEmployerId;
                contactsToUpdate.add(c);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
