    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> stagedRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            if (gift != null) {
                di.npsp__Contact1_Firstname__c = gift.firstName;
                di.npsp__Contact1_Lastname__c = gift.lastName;
                di.npsp__Contact1_Personal_Email__c = gift.email;
                di.npsp__Donation_Amount__c = gift.amount;
                di.npsp__Donation_Date__c = gift.giftDate;
                di.npsp__Donation_Donor__c = DONOR_CONTACT1;
            }
            stagedRecords.add(di);
        }

        insert stagedRecords;

        npsp__Data_Import_Settings__c settings = getDataImportSettings();

        npsp.BDI_DataImport_API.processDataImportRecords(
            settings,
            stagedRecords,
            false
        );

        Set<Id> stagedIds = new Set<Id>();
        for (npsp__DataImport__c di : stagedRecords) {
            stagedIds.add(di.Id);
        }

        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>(
            [
                SELECT
                    Id,
                    npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :stagedIds
            ]
        );

        for (npsp__DataImport__c staged : stagedRecords) {
            npsp__DataImport__c processed = processedById.get(staged.Id);
            if (processed == null) {
                processed = staged;
            }

            ImportResult res = new ImportResult();
            res.success = (processed.npsp__Status__c == STATUS_IMPORTED);
            res.contactId = processed.npsp__Contact1Imported__c;
            res.opportunityId = processed.npsp__DonationImported__c;
            res.errorMessage = res.success
                ? null
                : processed.npsp__FailureInformation__c;
            results.add(res);
        }

        return results;
    }

    private static npsp__Data_Import_Settings__c getDataImportSettings() {
        npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getOrgDefaults();
        if (settings == null || settings.Id == null) {
            settings = npsp__Data_Import_Settings__c.getInstance();
        }
        if (settings == null) {
            settings = new npsp__Data_Import_Settings__c();
        }

        if (String.isBlank(settings.npsp__Contact_Matching_Rule__c)) {
            settings.npsp__Contact_Matching_Rule__c = DEFAULT_CONTACT_MATCHING_RULE;
        }
        if (String.isBlank(settings.npsp__Donation_Matching_Behavior__c)) {
            settings.npsp__Donation_Matching_Behavior__c = DEFAULT_DONATION_MATCHING_BEHAVIOR;
        }

        return settings;
    }
