public with sharing class HouseholdService {
    private static final String HH_RECORD_TYPE_DEV_NAME = 'HH_Account';

    /**
     * Inserts the given new Contacts into a single new NPSP Household Account,
     * with the first Contact in the list designated as the primary contact.
     *
     * @param members The list of new Contacts to insert into one household.
     * @return The Id of the newly created Household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Household members list cannot be null or empty.');
        }

        // 1. Insert the first contact with a null AccountId.
        // In NPSP's Household Account model, inserting a Contact without an AccountId
        // automatically creates a Household Account (with the HH_Account record type),
        // sets the Contact as the Account's primary contact (npe01__One2OneContact__c),
        // and runs NPSP's automatic household naming and greetings logic.
        Contact primaryContact = members[0];
        primaryContact.AccountId = null;
        insert primaryContact;

        // 2. Query the AccountId generated by NPSP for the primary contact.
        Id householdAccountId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
            LIMIT 1
        ].AccountId;

        // Fallback safety in case NPSP trigger didn't create the Account (e.g. custom setting disabled in a minimal test context)
        if (householdAccountId == null) {
            Id hhRecordTypeId = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
                .get(HH_RECORD_TYPE_DEV_NAME)
                .getRecordTypeId();

            Account hhAccount = new Account(
                Name = 'Anonymous Household',
                RecordTypeId = hhRecordTypeId,
                npe01__One2OneContact__c = primaryContact.Id,
                npe01__SYSTEM_AccountType__c = 'Household Account',
                npe01__SYSTEMIsIndividual__c = true
            );
            insert hhAccount;
            householdAccountId = hhAccount.Id;

            primaryContact.AccountId = householdAccountId;
            update primaryContact;
        }

        // 3. If there are additional family members, link them to the same Household Account
        // and insert them in bulk so NPSP recalculates the household name & greetings once
        // without creating extra household accounts.
        if (members.size() > 1) {
            List<Contact> additionalMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i];
                member.AccountId = householdAccountId;
                additionalMembers.add(member);
            }
            insert additionalMembers;
        }

        return householdAccountId;
    }
}
