public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Request must specify both an Opportunity Id and a Contact Id.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be positive.');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Query 1: Opportunities for validation
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Cannot assign a partial soft credit to the Opportunity Primary Contact.');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException('Soft credit amount cannot exceed the Opportunity amount.');
            }
        }

        // Query 2: Existing OpportunityContactRoles for the relevant Opportunities and Contacts
        List<OpportunityContactRole> existingOcrs = [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIds
            ORDER BY CreatedDate ASC, Id ASC
        ];

        Map<String, List<OpportunityContactRole>> ocrMap = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingOcrs) {
            String key = getKey(ocr.OpportunityId, ocr.ContactId);
            if (!ocrMap.containsKey(key)) {
                ocrMap.put(key, new List<OpportunityContactRole>());
            }
            ocrMap.get(key).add(ocr);
        }

        // Query 3: Existing Partial Soft Credits for the relevant Opportunities and Contacts
        List<npsp__Partial_Soft_Credit__c> existingPscs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
            ORDER BY CreatedDate ASC, Id ASC
        ];

        Map<String, List<npsp__Partial_Soft_Credit__c>> pscMap = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
            String key = getKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscMap.containsKey(key)) {
                pscMap.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscMap.get(key).add(psc);
        }

        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<SObject> recordsToDelete = new List<SObject>();
        Map<String, OpportunityContactRole> activeOcrByKey = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = getKey(req.opportunityId, req.contactId);
            List<OpportunityContactRole> ocrs = ocrMap.get(key);
            List<npsp__Partial_Soft_Credit__c> pscs = pscMap.get(key);

            OpportunityContactRole targetOcr;

            if (ocrs != null && !ocrs.isEmpty()) {
                // Prefer the OCR already linked to the existing PSC if there are multiple OCRs
                if (pscs != null && !pscs.isEmpty() && String.isNotBlank(pscs[0].npsp__Contact_Role_ID__c)) {
                    String linkedOcrIdStr = pscs[0].npsp__Contact_Role_ID__c;
                    for (OpportunityContactRole ocr : ocrs) {
                        if (String.valueOf(ocr.Id) == linkedOcrIdStr || String.valueOf(ocr.Id).startsWith(linkedOcrIdStr)) {
                            targetOcr = ocr;
                            break;
                        }
                    }
                }
                if (targetOcr == null) {
                    targetOcr = ocrs[0];
                }

                // Any extra OCRs for the same Opportunity + Contact must be removed
                for (OpportunityContactRole ocr : ocrs) {
                    if (ocr.Id != targetOcr.Id) {
                        recordsToDelete.add(ocr);
                    }
                }

                if (targetOcr.Role != req.role) {
                    targetOcr.Role = req.role;
                    ocrsToUpsert.add(targetOcr);
                }
            } else {
                targetOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role,
                    IsPrimary = false
                );
                ocrsToUpsert.add(targetOcr);
            }

            activeOcrByKey.put(key, targetOcr);
        }

        // DML 1: Upsert OpportunityContactRoles so new ones get Ids and existing ones have the updated Role
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }

        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = getKey(req.opportunityId, req.contactId);
            OpportunityContactRole targetOcr = activeOcrByKey.get(key);
            List<npsp__Partial_Soft_Credit__c> pscs = pscMap.get(key);

            if (pscs != null && !pscs.isEmpty()) {
                npsp__Partial_Soft_Credit__c targetPsc = pscs[0];
                targetPsc.npsp__Amount__c = req.amount;
                targetPsc.npsp__Role_Name__c = req.role;
                targetPsc.npsp__Contact_Role_ID__c = String.valueOf(targetOcr.Id);
                pscsToUpsert.add(targetPsc);

                // Clean up any duplicate PSCs if they exist
                for (Integer i = 1; i < pscs.size(); i++) {
                    recordsToDelete.add(pscs[i]);
                }
            } else {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = String.valueOf(targetOcr.Id)
                );
                pscsToUpsert.add(newPsc);
            }
        }

        // DML 2: Upsert Partial Soft Credits
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }

        // DML 3: Delete any redundant OCRs (or PSCs)
        if (!recordsToDelete.isEmpty()) {
            delete recordsToDelete;
        }
    }

    private static String getKey(Id oppId, Id contactId) {
        return String.valueOf(oppId) + '_' + String.valueOf(contactId);
    }
}
