public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id cannot be null.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Donation amount must be greater than zero.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact with Id ' + contactId + ' does not exist.');
        }

        Contact donor = contacts[0];
        Date effectiveDate = (giftDate != null) ? giftDate : Date.today();

        String dateStr = effectiveDate.year() + '-' +
            String.valueOf(effectiveDate.month()).leftPad(2, '0') + '-' +
            String.valueOf(effectiveDate.day()).leftPad(2, '0');

        String contactFullName = String.isNotBlank(donor.FirstName)
            ? donor.FirstName + ' ' + donor.LastName
            : donor.LastName;

        String oppName = contactFullName + ' Donation ' + dateStr;
        String closedWonStage = getClosedWonStageName();

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = effectiveDate,
            StageName = closedWonStage
        );

        insert opp;

        reconcileContactRoles(opp.Id, donor.Id, donor.AccountId);
        reconcilePayments(opp.Id, amount, effectiveDate);

        return opp.Id;
    }

    private static String getClosedWonStageName() {
        List<OpportunityStage> stages = [
            SELECT MasterLabel, ApiName
            FROM OpportunityStage
            WHERE IsActive = true AND IsClosed = true AND IsWon = true
            ORDER BY SortOrder ASC
            LIMIT 1
        ];
        return stages.isEmpty() ? 'Closed Won' : stages[0].ApiName;
    }

    private static void reconcileContactRoles(Id oppId, Id donorId, Id householdAccountId) {
        Set<Id> householdMemberIds = new Set<Id>();
        if (householdAccountId != null) {
            for (Contact member : [
                SELECT Id
                FROM Contact
                WHERE AccountId = :householdAccountId AND Id != :donorId
            ]) {
                householdMemberIds.add(member.Id);
            }
        }

        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
            ORDER BY IsPrimary DESC, CreatedDate ASC
        ];

        Map<Id, OpportunityContactRole> keptRoleByContact = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpsert = new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existingRoles) {
            Boolean isValidContact = (ocr.ContactId == donorId) || householdMemberIds.contains(ocr.ContactId);
            if (!isValidContact || keptRoleByContact.containsKey(ocr.ContactId)) {
                rolesToDelete.add(ocr);
            } else {
                keptRoleByContact.put(ocr.ContactId, ocr);
            }
        }

        // Ensure Donor role for primary contact
        if (keptRoleByContact.containsKey(donorId)) {
            OpportunityContactRole donorOcr = keptRoleByContact.get(donorId);
            if (donorOcr.Role != 'Donor' || !donorOcr.IsPrimary) {
                donorOcr.Role = 'Donor';
                donorOcr.IsPrimary = true;
                rolesToUpsert.add(donorOcr);
            }
        } else {
            rolesToUpsert.add(new OpportunityContactRole(
                OpportunityId = oppId,
                ContactId = donorId,
                Role = 'Donor',
                IsPrimary = true
            ));
        }

        // Ensure Household Member role for every other member of the household
        for (Id memberId : householdMemberIds) {
            if (keptRoleByContact.containsKey(memberId)) {
                OpportunityContactRole memberOcr = keptRoleByContact.get(memberId);
                if (memberOcr.Role != 'Household Member' || memberOcr.IsPrimary) {
                    memberOcr.Role = 'Household Member';
                    memberOcr.IsPrimary = false;
                    rolesToUpsert.add(memberOcr);
                }
            } else {
                rolesToUpsert.add(new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = memberId,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpsert.isEmpty()) {
            upsert rolesToUpsert;
        }
    }

    private static void reconcilePayments(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
            ORDER BY CreatedDate ASC
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
        } else {
            npe01__OppPayment__c primaryPayment = existingPayments[0];
            if (primaryPayment.npe01__Payment_Amount__c != amount ||
                primaryPayment.npe01__Payment_Date__c != giftDate ||
                primaryPayment.npe01__Scheduled_Date__c != giftDate ||
                primaryPayment.npe01__Paid__c != true) {

                primaryPayment.npe01__Payment_Amount__c = amount;
                primaryPayment.npe01__Payment_Date__c = giftDate;
                primaryPayment.npe01__Scheduled_Date__c = giftDate;
                primaryPayment.npe01__Paid__c = true;
                update primaryPayment;
            }

            if (existingPayments.size() > 1) {
                List<npe01__OppPayment__c> duplicatePayments = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < existingPayments.size(); i++) {
                    duplicatePayments.add(existingPayments[i]);
                }
                delete duplicatePayments;
            }
        }
    }
}
