public with sharing class FamilyService {
    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Map<Id, Id> validPairs = new Map<Id, Id>();
        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null && childId != parentId) {
                validPairs.put(childId, parentId);
                childIds.add(childId);
                parentIds.add(parentId);
            }
        }

        if (validPairs.isEmpty()) {
            return;
        }

        // 1 SOQL query to find any existing relationship between any of the child and parent contacts in either direction
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE
                (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
                OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ]) {
            existingPairKeys.add(getPairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Insert only the forward relationship (Child -> Parent, Type = 'Parent').
        // NPSP's REL_Relationships_TDTM trigger automatically creates and links the
        // reciprocal relationship (Parent -> Child, Type = Son/Daughter/Child) using the List Setting.
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();
        for (Id childId : validPairs.keySet()) {
            Id parentId = validPairs.get(childId);
            String pairKey = getPairKey(childId, parentId);

            if (!existingPairKeys.contains(pairKey)) {
                relationshipsToInsert.add(
                    new npe4__Relationship__c(
                        npe4__Contact__c = childId,
                        npe4__RelatedContact__c = parentId,
                        npe4__Type__c = TYPE_PARENT,
                        npe4__Status__c = STATUS_CURRENT
                    )
                );
                // Prevent duplicate pairs if both (A => B) and (B => A) were somehow passed
                existingPairKeys.add(pairKey);
            }
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    private static String getPairKey(Id id1, Id id2) {
        String s1 = String.valueOf(id1);
        String s2 = String.valueOf(id2);
        return (s1 < s2) ? (s1 + '_' + s2) : (s2 + '_' + s1);
    }
}
