@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    @IsTest
    private static void rejectsReductionOfMoreThanHalf() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 499);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isTrue(newOpp.hasErrors(), 'Expected an error when Amount is reduced by more than half.');
        List<Database.Error> errors = newOpp.getErrors();
        Assert.areEqual(1, errors.size(), 'Expected exactly one error on the record.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Error message should match ERROR_MESSAGE.'
        );
    }

    @IsTest
    private static void acceptsBoundaryReductionOfExactlyHalf() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isFalse(newOpp.hasErrors(), 'A reduction of exactly half should be accepted.');
        Assert.areEqual(0, newOpp.getErrors().size(), 'Expected no errors on the record.');
    }

    @IsTest
    private static void acceptsAmountIncrease() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 1500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isFalse(newOpp.hasErrors(), 'An increase in Amount should be accepted.');
        Assert.areEqual(0, newOpp.getErrors().size(), 'Expected no errors on the record.');
    }

    @IsTest
    private static void acceptsPreviousNullAmountWithoutException() {
        Id oppId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldNullToValue = new Opportunity(Id = oppId1, Amount = null);
        Opportunity newNullToValue = new Opportunity(Id = oppId1, Amount = 100);
        Opportunity oldValueToNull = new Opportunity(Id = oppId2, Amount = 1000);
        Opportunity newValueToNull = new Opportunity(Id = oppId2, Amount = null);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newNullToValue, newValueToNull },
            new List<Opportunity>{ oldNullToValue, oldValueToNull }
        );

        Assert.isFalse(newNullToValue.hasErrors(), 'Record whose previous Amount was null should have no errors.');
        Assert.areEqual(0, newNullToValue.getErrors().size());
        Assert.isFalse(newValueToNull.hasErrors(), 'Record whose new Amount is null should have no errors.');
        Assert.areEqual(0, newValueToNull.getErrors().size());
    }

    @IsTest
    private static void handlesMixedBatchSelectivelyFlaggingInvalidRecords() {
        Id invalidId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validHalfId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validIncreaseId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validNullPrevId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id invalidId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldInvalid1 = new Opportunity(Id = invalidId1, Amount = 1000);
        Opportunity newInvalid1 = new Opportunity(Id = invalidId1, Amount = 499);

        Opportunity oldValidHalf = new Opportunity(Id = validHalfId, Amount = 1000);
        Opportunity newValidHalf = new Opportunity(Id = validHalfId, Amount = 500);

        Opportunity oldValidIncrease = new Opportunity(Id = validIncreaseId, Amount = 500);
        Opportunity newValidIncrease = new Opportunity(Id = validIncreaseId, Amount = 800);

        Opportunity oldValidNullPrev = new Opportunity(Id = validNullPrevId, Amount = null);
        Opportunity newValidNullPrev = new Opportunity(Id = validNullPrevId, Amount = 250);

        Opportunity oldInvalid2 = new Opportunity(Id = invalidId2, Amount = 200);
        Opportunity newInvalid2 = new Opportunity(Id = invalidId2, Amount = 50);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newInvalid1, newValidHalf, newValidIncrease, newValidNullPrev, newInvalid2 },
            new List<Opportunity>{ oldInvalid1, oldValidHalf, oldValidIncrease, oldValidNullPrev, oldInvalid2 }
        );

        Assert.isTrue(newInvalid1.hasErrors(), 'First invalid record should have an error.');
        Assert.areEqual(1, newInvalid1.getErrors().size());
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newInvalid1.getErrors()[0].getMessage()
        );

        Assert.isFalse(newValidHalf.hasErrors(), 'Exact half reduction record should not have errors.');
        Assert.areEqual(0, newValidHalf.getErrors().size());

        Assert.isFalse(newValidIncrease.hasErrors(), 'Increased Amount record should not have errors.');
        Assert.areEqual(0, newValidIncrease.getErrors().size());

        Assert.isFalse(newValidNullPrev.hasErrors(), 'Null previous Amount record should not have errors.');
        Assert.areEqual(0, newValidNullPrev.getErrors().size());

        Assert.isTrue(newInvalid2.hasErrors(), 'Second invalid record should have an error.');
        Assert.areEqual(1, newInvalid2.getErrors().size());
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newInvalid2.getErrors()[0].getMessage()
        );
    }
}
